# region: gather
def gather(raw):
    out = []
    for tok in raw[1:]:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: render
def render(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: intake
def intake(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: fold
def fold(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: sift
def sift(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return sift(fold(intake(shape(render(gather(raw))))))

